import java.nio.charset.StandardCharsets;

public final class JsonByteSize {
    private JsonByteSize() {}
    public static int utf8Bytes(String serializedJson) {
        return serializedJson.getBytes(StandardCharsets.UTF_8).length;
    }
    public static void main(String[] args) {
        // Fixed serialized texts, not a general JSON serializer.
        String[] json = {"{\"x\":1}", "{\"x\":\"中\"}", "{\"x\":\"\\u4e2d\"}",
                         "{\"x\":\"😀\"}", "{\"x\":\"\\\"\\\\\\n\"}", "{ \"x\": 1 }"};
        int[] expected = {7,11,14,12,14,10};
        for (int i=0;i<json.length;i++) {
            int bytes=utf8Bytes(json[i]);
            if(bytes!=expected[i]) throw new AssertionError(json[i]+": "+bytes);
            System.out.println(json[i]+" -> UTF-8 bytes="+bytes+", Java UTF-16 units="+json[i].length());
        }
        System.out.println("JsonByteSize: 6 fixed-encoding examples passed.");
    }
}

import java.io.ByteArrayOutputStream;
import java.nio.charset.StandardCharsets;
import java.util.Arrays;
import java.util.HexFormat;
import java.util.Random;

/** Teaching uint32 wire subset, not a general Protobuf parser or RPC protocol. */
public final class ProtobufVarint {
    public static byte[] encodeUInt32(long value) {
        if (value < 0 || value > 0xffff_ffffL) throw new IllegalArgumentException("uint32");
        ByteArrayOutputStream out = new ByteArrayOutputStream(5);
        do {
            int low = (int) (value & 0x7f);
            value >>>= 7;
            out.write(low | (value == 0 ? 0 : 0x80));
        } while (value != 0);
        return out.toByteArray();
    }
    public static long decodeUInt32(byte[] bytes) {
        if (bytes == null) throw new IllegalArgumentException("null");
        long result = 0;
        for (int i = 0; i < 5; i++) {
            if (i == bytes.length) throw new IllegalArgumentException("truncated");
            int b = bytes[i] & 0xff;
            if (i == 4 && (b & 0xf0) != 0) throw new IllegalArgumentException("overflow");
            result |= (long) (b & 0x7f) << (7 * i);
            if ((b & 0x80) == 0) {
                if (i + 1 != bytes.length) throw new IllegalArgumentException("trailing");
                return result;
            }
        }
        throw new IllegalArgumentException("too long");
    }
    public static long zigZag32(int value) {
        return Integer.toUnsignedLong((value << 1) ^ (value >> 31));
    }
    public static int unZigZag32(long value) {
        if (value < 0 || value > 0xffff_ffffL) throw new IllegalArgumentException("uint32");
        return (int) ((value >>> 1) ^ -(value & 1));
    }
    /** Schema: uint32 count = 1; string label = 2. Always emits both fields. */
    public static byte[] message(long count, String label) {
        if (label == null) throw new IllegalArgumentException("null label");
        byte[] text = label.getBytes(StandardCharsets.UTF_8);
        if (text.length > 1024) throw new IllegalArgumentException("label too large");
        ByteArrayOutputStream out = new ByteArrayOutputStream();
        out.write(0x08); // (1 << 3) | VARINT
        out.writeBytes(encodeUInt32(count));
        out.write(0x12); // (2 << 3) | LEN
        out.writeBytes(encodeUInt32(text.length));
        out.writeBytes(text);
        return out.toByteArray();
    }
    private static int checks;
    private static void check(boolean ok) { checks++; if (!ok) throw new AssertionError(checks); }
    private static void reject(Runnable op) {
        boolean rejected = false;
        try { op.run(); } catch (IllegalArgumentException expected) { rejected = true; }
        check(rejected);
    }
    public static void main(String[] args) {
        long[] values = {0, 1, 127, 128, 150, 16383, 16384, 0xffff_ffffL};
        String[] hex = {"00", "01", "7f", "8001", "9601", "ff7f", "808001", "ffffffff0f"};
        for (int i = 0; i < values.length; i++) {
            check(HexFormat.of().formatHex(encodeUInt32(values[i])).equals(hex[i])
                    && decodeUInt32(HexFormat.of().parseHex(hex[i])) == values[i]);
        }
        Random random = new Random(7321);
        for (int i = 0; i < 10000; i++) {
            long value = Integer.toUnsignedLong(random.nextInt());
            byte[] bytes = encodeUInt32(value);
            int expectedLength = value == 0 ? 1 : (64 - Long.numberOfLeadingZeros(value) + 6) / 7;
            check(bytes.length == expectedLength && decodeUInt32(bytes) == value);
        }
        for (int value : new int[]{0, -1, 1, Integer.MIN_VALUE, Integer.MAX_VALUE}) {
            check(unZigZag32(zigZag32(value)) == value);
        }
        check(Arrays.equals(message(150, "中"), HexFormat.of().parseHex("0896011203e4b8ad")));
        reject(() -> encodeUInt32(-1)); reject(() -> encodeUInt32(0x1_0000_0000L));
        for (String invalid : new String[]{"", "80", "80808080", "ffffffff10", "808080808000", "0000"}) {
            reject(() -> decodeUInt32(HexFormat.of().parseHex(invalid)));
        }
        reject(() -> message(1, "x".repeat(1025)));
        System.out.println("PASS " + checks + " checks; wire example=0896011203e4b8ad (8 bytes)");
    }
}

import java.nio.charset.StandardCharsets;
import java.util.Objects;

public final class SseCodecDemo {
    static String field(String text) {
        Objects.requireNonNull(text);
        if (text.length() > 128 || text.indexOf('\r') >= 0 || text.indexOf('\n') >= 0 || text.indexOf('\0') >= 0)
            throw new IllegalArgumentException("invalid SSE field");
        return text;
    }
    public static String encode(String id, String event, String data) {
        Objects.requireNonNull(data);
        if (data.getBytes(StandardCharsets.UTF_8).length > 65536)
            throw new IllegalArgumentException("event too large");
        StringBuilder out = new StringBuilder("id: ").append(field(id)).append('\n')
                .append("event: ").append(field(event)).append('\n');
        String normalized = data.replace("\r\n", "\n").replace('\r', '\n');
        for (String line : normalized.split("\n", -1)) out.append("data: ").append(line).append('\n');
        return out.append('\n').toString();
    }
    static int checks;
    static void check(boolean ok) { if (!ok) throw new AssertionError(); checks++; }
    static void bad(Runnable r) {
        try { r.run(); throw new AssertionError("expected validation failure"); }
        catch (IllegalArgumentException expected) { checks++; }
    }
    public static void main(String[] args) {
        check(encode("1", "delta", "甲🙂").equals("id: 1\nevent: delta\ndata: 甲🙂\n\n"));
        check(encode("2", "progress", "a\r\nb\rc\n").equals("id: 2\nevent: progress\ndata: a\ndata: b\ndata: c\ndata: \n\n"));
        check(encode("", "message", "").equals("id: \nevent: message\ndata: \n\n"));
        bad(() -> encode("1\nevent: evil", "delta", "x"));
        bad(() -> encode("1", "delta\r", "x"));
        bad(() -> encode("\0", "delta", "x"));
        bad(() -> encode("1", "delta", "界".repeat(22000)));
        check(encode("1", "delta", "x".repeat(65536)).endsWith("\n\n"));
        System.out.println("SseCodecDemo checks " + checks + " PASS; encoding only");
    }
}

import java.io.ByteArrayOutputStream;
import java.math.BigInteger;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Base64;
import java.util.List;
import java.util.Objects;
import java.util.Random;
import java.util.function.Consumer;

// Bounded teaching parser. Single-threaded, non-reentrant consumer; HTTP is outside it.
public final class SseIncremental {
    public record Event(String type, String data, String id) {}
    private final int maxLineBytes, maxDataChars;
    private final Consumer<Event> sink;
    private final ByteArrayOutputStream line = new ByteArrayOutputStream();
    private final StringBuilder data = new StringBuilder();
    private String eventType = "", idBuffer = "", lastEventId = "";
    private BigInteger retryMillis = BigInteger.valueOf(3000);
    private boolean skipLf, firstLine = true, closed;

    public SseIncremental(int maxLineBytes, int maxDataChars, Consumer<Event> sink) {
        if (maxLineBytes < 1 || maxDataChars < 1) throw new IllegalArgumentException("limits");
        this.maxLineBytes = maxLineBytes; this.maxDataChars = maxDataChars;
        this.sink = Objects.requireNonNull(sink);
    }
    public String lastEventId() { return lastEventId; }
    public BigInteger retryMillis() { return retryMillis; }
    public void feed(byte[] b, int off, int len) {
        if (closed) throw new IllegalStateException("parser ended or failed");
        Objects.checkFromIndexSize(off, len, b.length);
        try {
            for (int i = off; i < off + len; i++) {
                int value = b[i] & 255;
                if (skipLf) { skipLf = false; if (value == 10) continue; }
                if (value == 13 || value == 10) {
                    processLine();
                    skipLf = value == 13;
                } else {
                    if (line.size() == maxLineBytes) throw new IllegalArgumentException("line limit");
                    line.write(value);
                }
            }
        } catch (RuntimeException e) { closed = true; line.reset(); data.setLength(0); throw e; }
    }
    private void processLine() {
        // A valid UTF-8 multibyte character cannot contain CR or LF bytes.
        // Buffering the whole bounded line therefore preserves characters across reads.
        String s = line.toString(StandardCharsets.UTF_8); line.reset();
        if (firstLine) { firstLine = false; if (s.startsWith("\ufeff")) s = s.substring(1); }
        if (s.isEmpty()) {
            lastEventId = idBuffer;
            if (data.length() == 0) { eventType = ""; return; }
            Event event = new Event(eventType.isEmpty() ? "message" : eventType,
                    data.substring(0, data.length() - 1), lastEventId);
            data.setLength(0); eventType = "";
            sink.accept(event);
            return;
        }
        if (s.charAt(0) == ':') return;
        int colon = s.indexOf(':');
        String name = colon < 0 ? s : s.substring(0, colon);
        String value = colon < 0 ? "" : s.substring(colon + 1);
        if (value.startsWith(" ")) value = value.substring(1);
        switch (name) {
            case "data" -> {
                // Includes the LF added for each data line; limit is UTF-16 code units.
                if ((long)data.length() + value.length() + 1 > maxDataChars)
                    throw new IllegalArgumentException("event limit");
                data.append(value).append('\n');
            }
            case "event" -> eventType = value;
            case "id" -> { if (value.indexOf('\0') < 0) idBuffer = value; }
            case "retry" -> {
                if (!value.isEmpty() && value.chars().allMatch(c -> c >= '0' && c <= '9'))
                    retryMillis = new BigInteger(value);
            }
            default -> { } // Unknown fields are ignored.
        }
    }
    public void end() {
        // EOF is not a blank line. Incomplete final event is intentionally discarded.
        line.reset(); data.setLength(0); eventType = ""; closed = true;
    }
    static final String FIXTURE = "\ufeff: keepalive\r\nid: 7\r\nevent: delta\r\n"
            + "data: {\"text\":\"甲🙂\\\"}\\\"\"}\r\n\r\n"
            + "data: {\"n\":1,\rdata: \"ok\":true}\r\r"
            + "id:\nevent:\ndata: not-json\n\n";
    static final List<Event> EXPECTED = List.of(
            new Event("delta", "{\"text\":\"甲🙂\\\"}\\\"\"}", "7"),
            new Event("message", "{\"n\":1,\n\"ok\":true}", "7"),
            new Event("message", "not-json", ""));
    static int checks;
    static void check(boolean b) { if (!b) throw new AssertionError(); checks++; }
    static void reject(Runnable r) {
        try { r.run(); throw new AssertionError("expected failure"); }
        catch (IllegalArgumentException | IllegalStateException expected) { checks++; }
    }
    static SseIncremental parser(List<Event> out) { return new SseIncremental(4096,8192,out::add); }
    static void text(SseIncremental p, String s) {
        byte[] bytes = s.getBytes(StandardCharsets.UTF_8); p.feed(bytes,0,bytes.length);
    }
    public static void main(String[] args) {
        byte[] bytes = FIXTURE.getBytes(StandardCharsets.UTF_8);
        if (args.length == 1 && args[0].equals("--fixture")) {
            List<Event> out = new ArrayList<>(); SseIncremental p = parser(out);
            for (int i=0;i<bytes.length;i++) p.feed(bytes,i,1);
            p.end();
            for (Event e:out) System.out.println(Base64.getEncoder().encodeToString(e.data().getBytes(StandardCharsets.UTF_8)));
            return;
        }
        for (int cut=0;cut<=bytes.length;cut++) {
            List<Event> out = new ArrayList<>(); SseIncremental p = parser(out);
            p.feed(bytes,0,cut); p.feed(bytes,cut,bytes.length-cut); p.end();
            check(out.equals(EXPECTED));
        }
        Random r = new Random(6455);
        for (int trial=0;trial<1000;trial++) {
            List<Event> out = new ArrayList<>(); SseIncremental p = parser(out);
            for (int at=0;at<bytes.length;) { int n=Math.min(1+r.nextInt(9),bytes.length-at);p.feed(bytes,at,n);at+=n; }
            p.end(); check(out.equals(EXPECTED));
        }
        List<Event> out = new ArrayList<>(); SseIncremental p = parser(out);
        text(p,"data: {\"a\":"); check(out.isEmpty());
        text(p,"1}\n"); check(out.isEmpty()); text(p,"\n");
        check(out.equals(List.of(new Event("message","{\"a\":1}",""))));
        text(p,"id: old\n\n"); check(p.lastEventId().equals("old"));
        text(p,"id: bad\0id\ndata:\n\n"); check(out.get(1).equals(new Event("message","","old")));
        text(p,"data:  x:y\nx:ignored\n\n"); check(out.get(2).data().equals(" x:y"));
        text(p,"retry: 19\nretry: +3\nretry: ３\n"); check(p.retryMillis().equals(BigInteger.valueOf(19)));
        text(p,"retry: 99999999999999999999\n"); check(p.retryMillis().equals(new BigInteger("99999999999999999999")));
        int size=out.size(); text(p,"data: unfinished\n"); p.end(); check(out.size()==size);
        reject(() -> text(p,"\n"));
        List<Event> invalid = new ArrayList<>(); SseIncremental q=parser(invalid);
        byte[] malformed={'d','a','t','a',':',' ',(byte)0xff,10,10};q.feed(malformed,0,malformed.length);
        check(invalid.get(0).data().equals("\ufffd"));
        List<Event> tightOut=new ArrayList<>(); SseIncremental tight=new SseIncremental(7,3,tightOut::add);
        text(tight,"data: x\n\n"); check(tightOut.get(0).data().equals("x"));
        reject(() -> text(tight,"data: xx")); reject(() -> text(tight,"\n"));
        SseIncremental eventLimit=new SseIncremental(100,3,e -> {});
        reject(() -> text(eventLimit,"data: x\ndata: y\n\n"));
        List<Event> noData=new ArrayList<>(); SseIncremental no=parser(noData);
        text(no,"event: stale\n\ndata\n\n"); check(noData.get(0).type().equals("message"));
        List<Event> bom=new ArrayList<>(); SseIncremental bp=parser(bom);
        text(bp,"\ufeffdata: first\n\ndata: \ufeffkept\n\n");
        check(bom.size()==2 && bom.get(1).data().equals("\ufeffkept"));
        System.out.println("SseIncremental PASS " + checks + "; no HTTP/browser/reconnection integration");
    }
}

import com.sun.net.httpserver.HttpExchange;
import com.sun.net.httpserver.HttpServer;
import java.io.IOException;
import java.io.InputStream;
import java.net.InetSocketAddress;
import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.nio.charset.StandardCharsets;
import java.time.Duration;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicReference;

/** Java 21 loopback-only HTTP/SSE integration, not a production SDK.
 * Data is plain text in this small declared application protocol, not arbitrary JSON.
 * Request timeout bounds acquisition; a separate total-deadline watchdog closes the body.
 * No automatic retry, real credentials, external HTTP, or TLS configuration is involved.
 */
public final class HttpStreamClientDemo {
    sealed interface Message permits Text, Completed {}
    record Text(String value) implements Message {}
    record Completed(String result) implements Message {}
    record Result(List<Message> messages, int bytes) {}
    static final class StatusFailure extends IOException {
        final int status;
        StatusFailure(int status) { super("HTTP " + status); this.status = status; }
    }
    static final class ProtocolFailure extends RuntimeException {
        ProtocolFailure(String message) { super(message); }
    }

    static Result read(HttpClient client, ScheduledExecutorService timer,
                       URI uri, Duration budget, int maxBytes) throws Exception {
        if (!"http".equals(uri.getScheme()) || !"127.0.0.1".equals(uri.getHost())
                || uri.getUserInfo() != null || maxBytes < 1 || budget.isNegative() || budget.isZero())
            throw new IllegalArgumentException("loopback fixture and positive bounds required");
        var timedOut = new AtomicBoolean();
        var bodyRef = new AtomicReference<InputStream>();
        var watchdog = timer.schedule(() -> {
            timedOut.set(true);
            InputStream body = bodyRef.get();
            if (body != null) try { body.close(); } catch (IOException ignored) { }
        }, budget.toNanos(), TimeUnit.NANOSECONDS);
        try {
            var request = HttpRequest.newBuilder(uri).timeout(budget)
                    .header("Accept", "text/event-stream").GET().build();
            var response = client.send(request, HttpResponse.BodyHandlers.ofInputStream());
            try (InputStream body = response.body()) {
                bodyRef.set(body);
                // Deadline could have won before the handle became available.
                if (timedOut.get()) { body.close(); throw new IOException("total deadline"); }
                if (response.statusCode() != 200) throw new StatusFailure(response.statusCode());
                String type = response.headers().firstValue("Content-Type").orElse("")
                        .split(";", 2)[0].strip().toLowerCase(Locale.ROOT);
                if (!type.equals("text/event-stream")) throw new ProtocolFailure("content type");
                List<Message> messages = new ArrayList<>();
                AtomicBoolean terminal = new AtomicBoolean();
                SseIncremental parser = new SseIncremental(256, 512, event -> {
                    if (terminal.get()) throw new ProtocolFailure("event after terminal");
                    switch (event.type()) {
                        case "delta" -> messages.add(new Text(event.data()));
                        case "done" -> { messages.add(new Completed(event.data())); terminal.set(true); }
                        case "error" -> throw new ProtocolFailure("remote business error: " + event.data());
                        default -> throw new ProtocolFailure("unknown event type");
                    }
                });
                byte[] chunk = new byte[7]; // Deliberately unrelated to event / UTF-8 boundaries.
                int total = 0;
                try {
                    for (int n; !terminal.get() && (n = body.read(chunk)) != -1;) {
                        if (timedOut.get()) throw new IOException("total deadline");
                        if (n > maxBytes - total) throw new ProtocolFailure("body limit");
                        total += n;
                        parser.feed(chunk, 0, n);
                    }
                } finally { parser.end(); }
                if (timedOut.get()) throw new IOException("total deadline");
                if (!terminal.get()) throw new ProtocolFailure("EOF without terminal");
                return new Result(List.copyOf(messages), total);
            }
        } finally {
            bodyRef.set(null);
            watchdog.cancel(false);
        }
    }
    static void serve(HttpExchange exchange) throws IOException {
        try (exchange) {
            String path = exchange.getRequestURI().getPath();
            if (path.equals("/status")) { exchange.sendResponseHeaders(503, -1); return; }
            if (path.equals("/redirect")) {
                exchange.getResponseHeaders().set("Location", "/stream");
                exchange.sendResponseHeaders(302, -1); return;
            }
            exchange.getResponseHeaders().set("Content-Type",
                    path.equals("/type") ? "application/json" : "text/event-stream; charset=utf-8");
            exchange.sendResponseHeaders(200, 0);
            if (path.equals("/hang")) {
                exchange.getResponseBody().write(": open\n\n".getBytes(StandardCharsets.UTF_8));
                exchange.getResponseBody().flush();
                try { Thread.sleep(1200); } catch (InterruptedException e) { Thread.currentThread().interrupt(); }
                return;
            }
            String payload = switch (path) {
                case "/large" -> "event: delta\ndata: " + "a".repeat(200) + "\n\n";
                case "/incomplete" -> "event: delta\ndata: unfinished\n\n";
                case "/error" -> "event: error\ndata: failed\n\n";
                default -> "event: delta\ndata: 甲🙂\n\nevent: done\ndata: complete\n\n";
            };
            byte[] bytes = payload.getBytes(StandardCharsets.UTF_8);
            for (int i = 0; i < bytes.length; i += 3) {
                exchange.getResponseBody().write(bytes, i, Math.min(3, bytes.length - i));
                exchange.getResponseBody().flush();
            }
        } catch (IOException closedByClient) {
            // Early close from size, status, deadline or terminal is expected in these fixtures.
        }
    }
    interface Checked { void run() throws Exception; }
    static int checks;
    static void check(boolean ok) { if (!ok) throw new AssertionError(); checks++; }
    static void fails(Class<? extends Throwable> type, Checked action) throws Exception {
        try { action.run(); throw new AssertionError("expected " + type); }
        catch (Exception e) { if (!type.isInstance(e)) throw e; checks++; }
    }
    public static void main(String[] args) throws Exception {
        HttpServer server = HttpServer.create(new InetSocketAddress("127.0.0.1", 0), 0);
        var workers = Executors.newFixedThreadPool(2);
        var timer = Executors.newSingleThreadScheduledExecutor();
        server.setExecutor(workers); server.createContext("/", HttpStreamClientDemo::serve); server.start();
        URI root = URI.create("http://127.0.0.1:" + server.getAddress().getPort());
        try (HttpClient client = HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(1))
                .followRedirects(HttpClient.Redirect.NEVER).version(HttpClient.Version.HTTP_1_1).build()) {
            Duration budget = Duration.ofSeconds(2);
            Result result = read(client, timer, root.resolve("/stream"), budget, 1024);
            check(result.messages().equals(List.of(new Text("甲🙂"), new Completed("complete"))));
            check(result.bytes() > 0 && result.bytes() <= 1024);
            fails(StatusFailure.class, () -> read(client, timer, root.resolve("/status"), budget, 1024));
            fails(StatusFailure.class, () -> read(client, timer, root.resolve("/redirect"), budget, 1024));
            fails(ProtocolFailure.class, () -> read(client, timer, root.resolve("/type"), budget, 1024));
            fails(ProtocolFailure.class, () -> read(client, timer, root.resolve("/large"), budget, 64));
            fails(ProtocolFailure.class, () -> read(client, timer, root.resolve("/incomplete"), budget, 1024));
            fails(ProtocolFailure.class, () -> read(client, timer, root.resolve("/error"), budget, 1024));
            fails(IOException.class, () -> read(client, timer, root.resolve("/hang"), Duration.ofMillis(300), 1024));
            fails(IllegalArgumentException.class, () -> read(client, timer,
                    URI.create("http://example.test/"), budget, 1024));
        } finally {
            server.stop(0); workers.shutdownNow(); timer.shutdownNow();
            workers.awaitTermination(3, TimeUnit.SECONDS); timer.awaitTermination(3, TimeUnit.SECONDS);
        }
        System.out.println("HttpStreamClientDemo: " + checks + " checks passed (loopback HTTP only)");
    }
}

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.List;

/** In-memory bounded replay, not durable storage or a concurrent subscriber service. */
public final class ReplayWindow {
    record Event(long id, String data) {
        Event { if (id <= 0 || data == null || data.length() > 256) throw new IllegalArgumentException("event"); }
    }
    private final int capacity;
    private final ArrayDeque<Event> events = new ArrayDeque<>();
    private long last;
    public ReplayWindow(int capacity) {
        if (capacity < 1 || capacity > 1024) throw new IllegalArgumentException("capacity");
        this.capacity = capacity;
    }
    public synchronized Event append(String data) {
        if (data == null || data.length() > 256) throw new IllegalArgumentException("data");
        if (last == Long.MAX_VALUE) throw new IllegalStateException("sequence exhausted");
        Event e = new Event(++last, data); events.addLast(e);
        if (events.size() > capacity) events.removeFirst();
        return e;
    }
    public synchronized List<Event> after(long cursor) {
        if (cursor < 0 || cursor > last) throw new IllegalArgumentException("invalid cursor");
        if (!events.isEmpty() && cursor < events.getFirst().id() - 1)
            throw new IllegalStateException("snapshot required");
        List<Event> result = new ArrayList<>();
        for (Event e : events) if (e.id() > cursor) result.add(e);
        return List.copyOf(result);
    }
    static final class Reducer {
        long last; final StringBuilder text = new StringBuilder();
        boolean apply(Event e) {
            if (e.id() <= last) return false;
            if (last == Long.MAX_VALUE || e.id() != last + 1) throw new IllegalStateException("gap");
            if (text.length() + e.data().length() > 8192) throw new IllegalStateException("view limit");
            text.append(e.data()); last = e.id(); return true;
        }
    }
    static int checks;
    static void check(boolean b) { if (!b) throw new AssertionError(); checks++; }
    static void bad(Runnable r, Class<? extends RuntimeException> type) {
        try { r.run(); throw new AssertionError("expected failure"); }
        catch (RuntimeException e) { if (!type.isInstance(e)) throw e; checks++; }
    }
    public static void main(String[] args) {
        for (int cut = 0; cut <= 20; cut++) {
            ReplayWindow log = new ReplayWindow(20); Reducer ui = new Reducer();
            StringBuilder expected = new StringBuilder();
            for (int i = 0; i < 20; i++) { Event e = log.append("甲" + i + "🙂"); expected.append(e.data()); if (i < cut) check(ui.apply(e)); }
            // Replay includes an optional duplicate of the last applied event.
            long cursor = Math.max(0, cut - 1);
            for (Event e : log.after(cursor)) ui.apply(e);
            check(ui.text.toString().equals(expected.toString())); check(ui.last == 20);
            check(log.after(20).isEmpty());
        }
        ReplayWindow shortLog = new ReplayWindow(2); shortLog.append("a"); shortLog.append("b"); shortLog.append("c");
        bad(() -> shortLog.after(0), IllegalStateException.class);
        check(shortLog.after(1).equals(List.of(new Event(2,"b"), new Event(3,"c"))));
        bad(() -> shortLog.after(-1), IllegalArgumentException.class); bad(() -> shortLog.after(4), IllegalArgumentException.class);
        bad(() -> shortLog.append("x".repeat(257)), IllegalArgumentException.class);
        bad(() -> new ReplayWindow(0), IllegalArgumentException.class);
        Reducer gap = new Reducer(); bad(() -> gap.apply(new Event(2,"b")), IllegalStateException.class);
        check(gap.apply(new Event(1,"a"))); check(!gap.apply(new Event(1,"a")));
        check(gap.text.toString().equals("a"));
        Reducer large = new Reducer(); for(int i=1;i<=32;i++) large.apply(new Event(i,"x".repeat(256)));
        bad(() -> large.apply(new Event(33,"x")), IllegalStateException.class);
        bad(() -> new Event(0,"x"), IllegalArgumentException.class);
        bad(() -> new Event(1,null), IllegalArgumentException.class);
        bad(() -> new Event(1,"x".repeat(257)), IllegalArgumentException.class);
        bad(() -> new ReplayWindow(1025), IllegalArgumentException.class);
        ReplayWindow exhausted = new ReplayWindow(1); exhausted.last = Long.MAX_VALUE;
        bad(() -> exhausted.append("x"), IllegalStateException.class);
        System.out.println("PASS " + checks + "; bounded replay/reducer only");
    }
}

import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicInteger;

/** Local cooperative state machine; NOT a provider cancellation API. */
public final class CancelGeneration {
    enum State { RUNNING, CANCEL_REQUESTED, CANCELLED, COMPLETED, FAILED }
    private State state = State.RUNNING;
    private Runnable upstream;
    private boolean hookClaimed;
    private final List<String> tokens = new ArrayList<>();
    private Runnable claimHook() {
        if ((state != State.CANCEL_REQUESTED && state != State.CANCELLED) || upstream == null || hookClaimed) return null;
        hookClaimed = true;
        return upstream;
    }
    // Hook execution is outside the monitor. A thrown hook leaves cancellation pending.
    public void attach(Runnable hook) {
        if (hook == null) throw new IllegalArgumentException("null hook");
        Runnable action;
        synchronized (this) {
            if (upstream != null) throw new IllegalStateException("already attached");
            upstream = hook;
            action = claimHook();
        }
        if (action != null) action.run();
    }
    public boolean requestCancel() {
        Runnable action;
        synchronized (this) {
            if (state != State.RUNNING) return false;
            state = State.CANCEL_REQUESTED;
            action = claimHook();
        }
        if (action != null) action.run();
        return true;
    }
    public synchronized boolean emit(String token) {
        if (token == null || token.length() > 32) throw new IllegalArgumentException("token");
        if (state != State.RUNNING) return false;
        if (tokens.size() == 32) { state = State.FAILED; return false; }
        tokens.add(token);
        return true;
    }
    public synchronized void acknowledgeStopped() {
        if (state == State.CANCEL_REQUESTED) state = State.CANCELLED;
    }
    public synchronized void complete() {
        if (state == State.RUNNING) state = State.COMPLETED;
        // A completion callback alone is not proof that a requested cancellation stopped work.
    }
    public synchronized State state() { return state; }
    public synchronized List<String> snapshot() { return List.copyOf(tokens); }
    private static int checks;
    private static void check(boolean v) { if (!v) throw new AssertionError(); checks++; }
    private static void await(CountDownLatch l) throws InterruptedException {
        if (!l.await(2, TimeUnit.SECONDS)) throw new AssertionError("latch timeout");
    }
    private static void join(Thread t) throws InterruptedException {
        t.join(2000); if (t.isAlive()) { t.interrupt(); throw new AssertionError("thread leak"); }
    }
    public static void main(String[] args) throws Exception {
        CancelGeneration late = new CancelGeneration(); AtomicInteger calls = new AtomicInteger();
        check(late.requestCancel()); check(late.state() == State.CANCEL_REQUESTED);
        check(!late.emit("late")); late.attach(calls::incrementAndGet);
        check(calls.get() == 1); check(!late.requestCancel());
        late.complete(); check(late.state() == State.CANCEL_REQUESTED);
        late.acknowledgeStopped(); check(late.state() == State.CANCELLED);
        CancelGeneration afterStop = new CancelGeneration(); afterStop.requestCancel(); afterStop.acknowledgeStopped();
        AtomicInteger lateHooks = new AtomicInteger(); afterStop.attach(lateHooks::incrementAndGet); check(lateHooks.get() == 1);
        CancelGeneration done = new CancelGeneration(); done.complete();
        check(!done.requestCancel()); check(done.state() == State.COMPLETED);
        CancelGeneration broken = new CancelGeneration();
        broken.attach(() -> { throw new IllegalStateException("transport failure"); });
        try { broken.requestCancel(); throw new AssertionError(); }
        catch (IllegalStateException expected) { check(broken.state() == State.CANCEL_REQUESTED); }
        CancelGeneration live = new CancelGeneration(); CountDownLatch started = new CountDownLatch(1);
        Thread worker = new Thread(() -> {
            try { live.emit("first"); started.countDown(); Thread.sleep(10000); live.emit("unwanted"); }
            catch (InterruptedException expected) { Thread.currentThread().interrupt(); }
            finally { live.acknowledgeStopped(); }
        });
        AtomicInteger interrupts = new AtomicInteger();
        live.attach(() -> { interrupts.incrementAndGet(); worker.interrupt(); });
        worker.start(); await(started); check(live.requestCancel()); join(worker);
        check(interrupts.get() == 1); check(live.state() == State.CANCELLED);
        check(live.snapshot().equals(List.of("first"))); check(!live.emit("after"));
        for (int i = 0; i < 300; i++) {
            CancelGeneration race = new CancelGeneration(); AtomicInteger hooks = new AtomicInteger();
            CountDownLatch go = new CountDownLatch(1);
            Thread a = new Thread(() -> { try { await(go); race.requestCancel(); } catch (InterruptedException e) { throw new AssertionError(e); } });
            Thread b = new Thread(() -> { try { await(go); race.attach(hooks::incrementAndGet); } catch (InterruptedException e) { throw new AssertionError(e); } });
            a.start(); b.start(); go.countDown(); join(a); join(b);
            check(hooks.get() == 1); check(race.state() == State.CANCEL_REQUESTED);
            check(!race.requestCancel()); race.acknowledgeStopped(); check(race.state() == State.CANCELLED);
        }
        for (int i = 0; i < 300; i++) {
            CancelGeneration race = new CancelGeneration(); AtomicInteger hooks = new AtomicInteger(); race.attach(hooks::incrementAndGet);
            CountDownLatch go = new CountDownLatch(1);
            Thread a = new Thread(() -> { try { await(go); race.requestCancel(); } catch (InterruptedException e) { throw new AssertionError(e); } });
            Thread b = new Thread(() -> { try { await(go); race.complete(); } catch (InterruptedException e) { throw new AssertionError(e); } });
            a.start(); b.start(); go.countDown(); join(a); join(b);
            State s = race.state(); check(s == State.COMPLETED || s == State.CANCEL_REQUESTED);
            check(hooks.get() == (s == State.CANCEL_REQUESTED ? 1 : 0)); check(!race.emit("post terminal"));
        }
        CancelGeneration full = new CancelGeneration(); for (int i = 0; i < 32; i++) check(full.emit("x"));
        check(!full.emit("overflow")); check(full.state() == State.FAILED); check(full.snapshot().size() == 32);
        System.out.println("PASS " + checks + "; local state and real cooperative threads only");
    }
}

import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicInteger;

/** Bounded local permit/feedback core, not an HTTP client or production controller. */
public final class AdaptiveLimit {
    public enum Signal { HEALTHY, OVERLOADED, NEUTRAL }
    public static final class Permit {
        private final AdaptiveLimit owner;
        private final long epoch;
        private boolean ended;
        private Permit(AdaptiveLimit owner, long epoch) { this.owner = owner; this.epoch = epoch; }
    }
    private final int min, max, minSamples;
    private final long interval;
    private int limit, inFlight, samples;
    private boolean overloaded, saturated;
    private long epoch, lastUpdate, lastObserved;
    public AdaptiveLimit(int min, int initial, int max, int minSamples, long interval) {
        if (min < 1 || min > initial || initial > max || max > 100_000 ||
                minSamples < 1 || minSamples > 100_000 || interval < 1)
            throw new IllegalArgumentException();
        this.min = min; this.limit = initial; this.max = max;
        this.minSamples = minSamples; this.interval = interval;
    }
    public synchronized Permit tryAcquire() {
        if (inFlight >= limit) { saturated = true; return null; }
        inFlight++; saturated |= inFlight >= limit;
        return new Permit(this, epoch);
    }
    /** Invoke only when this attempt has actually released its tracked resource. */
    public synchronized boolean finish(Permit p, Signal signal) {
        if (p == null || p.owner != this || signal == null) throw new IllegalArgumentException();
        if (p.ended) return false;
        p.ended = true; inFlight--;
        if (p.epoch == epoch && signal != Signal.NEUTRAL) {
            if (samples < Integer.MAX_VALUE) samples++;
            overloaded |= signal == Signal.OVERLOADED;
        }
        return true;
    }
    /** Relative monotonic nanoseconds. The caller supplies the sampling clock. */
    public synchronized int update(long now) {
        if (now < lastObserved || now < 0) throw new IllegalArgumentException();
        lastObserved = now;
        if (now - lastUpdate < interval || samples < minSamples) return limit;
        if (epoch == Long.MAX_VALUE) throw new IllegalStateException("epoch exhausted");
        if (overloaded) limit = Math.max(min, limit / 2);
        else if (saturated && limit < max) limit++;
        epoch++; lastUpdate = now; samples = 0; overloaded = false;
        saturated = inFlight >= limit;
        return limit;
    }
    public synchronized int limit() { return limit; }
    public synchronized int inFlight() { return inFlight; }
    private static int checks;
    private static void check(boolean ok) { if (!ok) throw new AssertionError(); checks++; }
    private static List<Permit> fill(AdaptiveLimit c) {
        List<Permit> ps = new ArrayList<>(); Permit p;
        while ((p = c.tryAcquire()) != null) ps.add(p);
        return ps;
    }
    public static void main(String[] args) throws Exception {
        AdaptiveLimit c = new AdaptiveLimit(1, 4, 8, 1, 100);
        List<Permit> ps = fill(c); check(ps.size() == 4); check(c.inFlight() == 4);
        check(c.update(100) == 4); // no completion: no growth
        check(c.finish(ps.get(0), Signal.OVERLOADED));
        check(!c.finish(ps.get(0), Signal.HEALTHY));
        check(c.limit() == 4); check(c.update(100) == 2);
        check(c.inFlight() == 3); check(c.tryAcquire() == null);
        for (int i = 1; i < ps.size(); i++) check(c.finish(ps.get(i), Signal.HEALTHY));
        check(c.inFlight() == 0); check(c.update(200) == 2); // old epoch successes ignored
        for (int round = 0; round < 10; round++) {
            ps = fill(c); for (Permit p : ps) c.finish(p, Signal.HEALTHY);
            int before = c.limit(); check(c.update(300 + round * 100L) == Math.min(8, before + 1));
        }
        for (int round = 0; round < 10; round++) {
            ps = fill(c); for (Permit p : ps) c.finish(p, Signal.OVERLOADED);
            int before = c.limit(); check(c.update(1400 + round * 100L) == Math.max(1, before / 2));
        }
        c = new AdaptiveLimit(1, 4, 8, 2, 100);
        Permit p = c.tryAcquire(); c.finish(p, Signal.HEALTHY);
        check(c.update(100) == 4); // insufficient samples
        p = c.tryAcquire(); c.finish(p, Signal.HEALTHY); check(c.update(100) == 4); // app limited
        try { c.update(99); throw new AssertionError(); }
        catch (IllegalArgumentException expected) { checks++; }
        p = c.tryAcquire(); c.finish(p, Signal.NEUTRAL); check(c.update(200) == 4);
        try { c.finish(new AdaptiveLimit(1, 1, 1, 1, 1).tryAcquire(), Signal.HEALTHY); throw new AssertionError(); }
        catch (IllegalArgumentException expected) { checks++; }
        try { new AdaptiveLimit(0, 1, 2, 1, 1); throw new AssertionError(); }
        catch (IllegalArgumentException expected) { checks++; }
        AdaptiveLimit shared = new AdaptiveLimit(1, 7, 7, 4, 100);
        AtomicInteger active = new AtomicInteger(), peak = new AtomicInteger(), finished = new AtomicInteger();
        ExecutorService pool = Executors.newFixedThreadPool(16);
        try {
            List<Future<?>> fs = new ArrayList<>();
            for (int t = 0; t < 16; t++) fs.add(pool.submit(() -> {
                for (int n = 0; n < 2000; n++) {
                    Permit permit = shared.tryAcquire();
                    if (permit == null) { Thread.yield(); continue; }
                    int a = active.incrementAndGet(); peak.accumulateAndGet(a, Math::max);
                    if (a > 7) throw new AssertionError("capacity exceeded");
                    try { Thread.yield(); } finally {
                        active.decrementAndGet();
                        if (!shared.finish(permit, Signal.HEALTHY)) throw new AssertionError();
                        if (shared.finish(permit, Signal.HEALTHY)) throw new AssertionError();
                        finished.incrementAndGet();
                    }
                }
            }));
            for (Future<?> f : fs) f.get(10, TimeUnit.SECONDS);
        } finally {
            pool.shutdownNow(); if (!pool.awaitTermination(5, TimeUnit.SECONDS)) throw new AssertionError();
        }
        check(peak.get() >= 1 && peak.get() <= 7); check(finished.get() > 0);
        check(shared.inFlight() == 0); check(active.get() == 0);
        System.out.println("PASS " + checks + " deterministic assertions; " + finished.get() +
                " real concurrent permit lifecycles, peak=" + peak.get() + "; no downstream requests");
    }
}

import java.time.Instant;
import java.util.Set;

public final class AuthDecision {
    // Created ONLY by a trusted, already-validated token/session adapter.
    // This class does not decode JWTs or verify cryptographic signatures.
    public record VerifiedIdentity(String userId, String tenantId,
                                   Instant expiresAt, Set<String> scopes) {
        public VerifiedIdentity { scopes = Set.copyOf(scopes); }
    }
    public record Resource(String tenantId, String ownerId) {}
    public static int status(VerifiedIdentity identity, Instant now,
                             String requiredScope, Resource resource) {
        if (identity == null || !now.isBefore(identity.expiresAt())) return 401;
        if (!identity.scopes().contains(requiredScope)) return 403;
        if (resource != null && (!identity.tenantId().equals(resource.tenantId())
                || !identity.userId().equals(resource.ownerId()))) return 403;
        return 200;
    }
    private static void expect(int expected, int actual) {
        if (expected != actual) throw new AssertionError(expected + " != " + actual);
    }
    public static void main(String[] args) {
        Instant expiry = Instant.ofEpochSecond(1000);
        var identity = new VerifiedIdentity("u1", "t1", expiry, Set.of("edit"));
        var mine = new Resource("t1", "u1");
        expect(401, status(null, expiry.minusSeconds(1), "edit", mine));
        expect(200, status(identity, expiry.minusSeconds(1), "edit", mine));
        expect(401, status(identity, expiry, "edit", mine));
        expect(401, status(identity, expiry.plusSeconds(1), "edit", mine));
        expect(403, status(identity, expiry.minusSeconds(1), "admin", mine));
        expect(403, status(identity, expiry.minusSeconds(1), "edit", new Resource("t2", "u1")));
        expect(403, status(identity, expiry.minusSeconds(1), "edit", new Resource("t1", "u2")));
        expect(200, status(identity, expiry.minusSeconds(1), "edit", null));
        System.out.println("AuthDecision: 8 cases passed; pure authorization logic only, no JWT/Spring integration test.");
    }
}

import java.util.*;
public final class RbacPolicy {
    public record Principal(String id,String tenant,Set<String> activeRoles) {
        public Principal {activeRoles=Set.copyOf(activeRoles);}
    }
    public record Resource(String tenant,String owner) {}
    private final Map<String,Set<String>> rolePermissions;
    public RbacPolicy(Map<String,Set<String>> input) {
        Map<String,Set<String>> copy=new HashMap<>();
        input.forEach((k,v)->copy.put(k,Set.copyOf(v)));rolePermissions=Map.copyOf(copy);
    }
    // The principal and active roles must come from trusted server-side state.
    public boolean allows(Principal p,String permission,Resource resource,boolean ownerOnly) {
        if(p==null || resource==null || !p.tenant().equals(resource.tenant()))return false;
        if(ownerOnly && !p.id().equals(resource.owner()))return false;
        return p.activeRoles().stream().anyMatch(role->rolePermissions.getOrDefault(role,Set.of()).contains(permission));
    }
    public static void main(String[] args) {
        var policy=new RbacPolicy(Map.of("reader",Set.of("post:read"),"editor",Set.of("post:read","post:edit")));
        var editor=new Principal("u1","t1",Set.of("editor"));
        var reader=new Principal("u1","t1",Set.of("reader"));
        var own=new Resource("t1","u1");
        boolean[] checks={policy.allows(editor,"post:edit",own,true),
          !policy.allows(reader,"post:edit",own,true),policy.allows(reader,"post:read",own,false),
          !policy.allows(editor,"post:delete",own,false),!policy.allows(null,"post:read",own,false),
          !policy.allows(editor,"post:edit",new Resource("t2","u1"),false),
          !policy.allows(editor,"post:edit",new Resource("t1","u2"),true),
          !policy.allows(new Principal("u1","t1",Set.of("unknown")),"post:read",own,false)};
        for(boolean c:checks)if(!c)throw new AssertionError();
        System.out.println("RbacPolicy: 8 checks passed; flat RBAC plus explicit tenant/owner constraints; no database/cache or role-administration integration.");
    }
}

import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.*;

/** Local transition model only. Token objects are NOT serialized credentials. */
public final class RefreshFamily {
    public enum Status { ROTATED, REUSED, REVOKED, EXPIRED, INVALID, LIMIT }
    public static final class Token {
        private final RefreshFamily owner;
        private final int generation;
        private Token(RefreshFamily owner, int generation) {
            this.owner = owner; this.generation = generation;
        }
    }
    public record Result(Status status, Token next) {}
    private final long expiresAt;
    private final int maxRotations;
    private Token current = new Token(this, 0);
    private boolean revoked;
    public RefreshFamily(long expiresAt, int maxRotations) {
        if (expiresAt <= 0 || maxRotations < 1 || maxRotations > 1024)
            throw new IllegalArgumentException();
        this.expiresAt = expiresAt; this.maxRotations = maxRotations;
    }
    public synchronized Token initial() {
        if (current.generation != 0 || revoked) throw new IllegalStateException();
        return current;
    }
    public synchronized Result rotate(Token token, long now) {
        if (now < 0) throw new IllegalArgumentException();
        if (token == null || token.owner != this) return new Result(Status.INVALID, null);
        if (revoked) return new Result(Status.REVOKED, null);
        if (now >= expiresAt) { revoked = true; return new Result(Status.EXPIRED, null); }
        if (token != current) { revoked = true; return new Result(Status.REUSED, null); }
        if (current.generation >= maxRotations) {
            revoked = true; return new Result(Status.LIMIT, null);
        }
        current = new Token(this, current.generation + 1);
        return new Result(Status.ROTATED, current);
    }
    public synchronized void revoke() { revoked = true; }
    private static int checks;
    private static void check(boolean ok) { if (!ok) throw new AssertionError(); checks++; }
    public static void main(String[] args) throws Exception {
        RefreshFamily f = new RefreshFamily(100, 8);
        Token first = f.initial();
        check(f.rotate(null, 0).status == Status.INVALID);
        check(f.rotate(new RefreshFamily(100, 1).initial(), 0).status == Status.INVALID);
        Result second = f.rotate(first, 1); check(second.status == Status.ROTATED);
        Result third = f.rotate(second.next, 2); check(third.status == Status.ROTATED);
        check(f.rotate(first, 3).status == Status.REUSED);
        check(f.rotate(third.next, 4).status == Status.REVOKED);
        f = new RefreshFamily(10, 2); first = f.initial();
        second = f.rotate(first, 9); check(second.status == Status.ROTATED);
        check(f.rotate(second.next, 10).status == Status.EXPIRED);
        f = new RefreshFamily(100, 1); first = f.initial();
        second = f.rotate(first, 1); check(second.status == Status.ROTATED);
        check(f.rotate(second.next, 2).status == Status.LIMIT);
        f = new RefreshFamily(100, 2); first = f.initial(); f.revoke(); f.revoke();
        check(f.rotate(first, 0).status == Status.REVOKED);
        try { new RefreshFamily(0, 1); throw new AssertionError(); }
        catch (IllegalArgumentException expected) { checks++; }
        try { new RefreshFamily(1, 1025); throw new AssertionError(); }
        catch (IllegalArgumentException expected) { checks++; }
        f = new RefreshFamily(100, 1024); Token token = f.initial();
        for (int i = 0; i < 1024; i++) {
            Result r = f.rotate(token, 0); check(r.status == Status.ROTATED); token = r.next;
        }
        check(f.rotate(token, 0).status == Status.LIMIT);
        ExecutorService pool = Executors.newFixedThreadPool(8);
        try {
            for (int round = 0; round < 200; round++) {
                RefreshFamily family = new RefreshFamily(100, 8);
                Token shared = family.initial(); CountDownLatch start = new CountDownLatch(1);
                List<Future<Result>> futures = new ArrayList<>();
                for (int i = 0; i < 8; i++) futures.add(pool.submit(() -> {
                    if (!start.await(5, TimeUnit.SECONDS)) throw new AssertionError();
                    return family.rotate(shared, 1);
                }));
                start.countDown(); int rotated = 0, reused = 0, revokedCount = 0;
                Token winner = null;
                for (Future<Result> future : futures) {
                    Result r = future.get(5, TimeUnit.SECONDS);
                    if (r.status == Status.ROTATED) { rotated++; winner = r.next; }
                    else if (r.status == Status.REUSED) reused++;
                    else if (r.status == Status.REVOKED) revokedCount++;
                    else throw new AssertionError();
                }
                check(rotated == 1); check(reused == 1); check(revokedCount == 6);
                check(family.rotate(winner, 2).status == Status.REVOKED);
            }
        } finally {
            pool.shutdownNow(); if (!pool.awaitTermination(5, TimeUnit.SECONDS)) throw new AssertionError();
        }
        System.out.println("PASS " + checks + " local family transition checks; no OAuth service or credentials");
    }
}

// A single authenticated-session store. Text messages only, no offline send queue.
// Contract: subscribers may stop/start synchronously but must not throw.
// Injected makeSocket/schedule/cancel must not synchronously re-enter the store;
// schedule must return a handle before invoking its callback asynchronously.
// Socket construction failures retry; subscriber/scheduler/cancel exceptions are not isolated.
export function createSocketStore(url, options = {}) {
  const {
    makeSocket = u => new WebSocket(u),
    schedule = (f, ms) => setTimeout(f, ms),
    cancel = id => clearTimeout(id),
    random = Math.random,
    maxRetries = 7,
    maxBytes = 65536,
    highWaterBytes = 262144,
  } = options;
  let running = false, socket = null, timer = null, epoch = 0, attempts = 0;
  const listeners = new Set();
  const initial = Object.freeze({ status: 'idle', message: null });
  let state = initial;
  const bytes = text => new TextEncoder().encode(text).byteLength;
  const emit = patch => {
    state = Object.freeze({ ...state, ...patch });
    for (const listener of [...listeners]) listener();
  };
  const alive = (ws, generation) => running && socket === ws && epoch === generation;
  function retry() {
    if (!running || timer !== null) return;
    if (attempts >= maxRetries) { emit({ status: 'failed' }); return; }
    const delay = Math.floor(Math.min(30000, 500 * 2 ** attempts++) * (0.5 + random() * 0.5));
    const generation = epoch;
    emit({ status: 'retrying' });
    if (!running || epoch !== generation) return;
    timer = schedule(() => {
      if (!running || epoch !== generation) return;
      timer = null; connect();
    }, delay);
  }
  function connect() {
    const generation = ++epoch;
    let ws;
    emit({ status: 'connecting' });
    if (!running || epoch !== generation) return;
    try { ws = makeSocket(url); socket = ws; }
    catch { socket = null; retry(); return; }
    ws.onopen = () => {
      if (!alive(ws, generation)) return;
      attempts = 0; emit({ status: 'open' });
    };
    ws.onmessage = event => {
      if (!alive(ws, generation)) return;
      if (typeof event.data !== 'string' || bytes(event.data) > maxBytes) {
        running = false; ++epoch; socket = null;
        emit({ status: 'protocol-error' }); ws.close(4009, 'invalid message size/type'); return;
      }
      emit({ message: event.data });
    };
    ws.onerror = () => { /* Browser close event determines reconnect policy. */ };
    ws.onclose = event => {
      if (!alive(ws, generation)) return;
      socket = null;
      if ([1000, 1008, 4401, 4403].includes(event.code)) {
        running = false; emit({ status: 'closed' }); return;
      }
